// Generated by philote from page /horses/[id]. PageBody's body is written by
// a model and pinned in philote.lock (decision-2).
/* eslint-disable @typescript-eslint/no-unused-vars -- every page gets the same imports */
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { Suspense } from "react";

import * as Icons from "lucide-react";

import { horses } from "@/lib/api";
import { readHorseView } from "@/lib/reads";
import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";

import HorseView from "@/components/common/horse-view";

export const metadata: Metadata = { title: "Horse" };

export default function Page({ params }: PageProps<"/horses/[id]">) {
    return (
        <main className="flex flex-1 flex-col">
            <PageBody
                title={"Horse"}
                content={(className) => (
                    <div className={className}>
                        <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                            <Record params={params} />
                        </Suspense>
                    </div>
                )}
            />
        </main>
    );
}

// Record streams in after the page's shell, so a missing record renders
// not-found.tsx with noindex, but the response status stays 200.
async function Record({ params }: Pick<PageProps<"/horses/[id]">, "params">) {
    await connection();
    const { id } = await params;
    const result = await horses.get(id);
    if (!result.ok) {
        notFound();
    }
    const item = await readHorseView(result.value);
    return <HorseView {...item} />;
}

type PageBodyProps = {
    title: string;
    content: (className: string) => React.ReactNode;
};

function PageBody({ title, content }: PageBodyProps): React.ReactNode {
    return (
        <div className="mx-auto flex w-full max-w-2xl flex-col gap-4 px-4 py-6 sm:px-6 sm:py-10 lg:gap-6">
            <div className="flex items-center gap-2">
                <Badge variant="secondary" className="gap-1 rounded-xl">
                    <Icons.Heart className="size-3.5 text-primary" />
                    <span className="font-heading text-xs tracking-wide uppercase">{title}</span>
                </Badge>
                <Separator className="flex-1" />
            </div>
            {content("w-full rounded-2xl bg-card text-card-foreground border shadow-sm")}
        </div>
    );
}
